def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = {k: v for k, v in opponents_status.items() if v.get('alive')}
    if not alive:
        return float(min(budget, 20.0))

    cindy = opponents_status.get('Cindy')
    main_opp = None
    if cindy and cindy.get('alive'):
        main_opp = cindy
    else:
        best_budget = -1
        for opp in alive.values():
            if opp.get('budget', 0) > best_budget:
                best_budget = opp.get('budget', 0)
                main_opp = opp

    prev_bid = None
    opp_hp = 5
    opp_budget = 0
    opp_req = WATER_REQ
    if main_opp is not None:
        opp_hp = main_opp.get('hp', 5)
        opp_budget = main_opp.get('budget', 0)
        opp_req = main_opp.get('water_requirement', WATER_REQ)
        prev = main_opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            prev_bid = float(prev.get('bid'))

    units = supply / float(WATER_REQ)
    scarcity = units < 2.0
    very_tight = supply <= 18.0
    abundant = supply >= 24.0

    critical_me = hp <= 2 or no_water_days >= 1
    critical_opp = opp_hp <= 2 or (main_opp is not None and main_opp.get('no_water_days', 0) >= 1)

    if prev_bid is None:
        if critical_me:
            bid = 96.0
        elif scarcity:
            bid = 82.0
        else:
            bid = 48.0
    else:
        if critical_me:
            bid = max(prev_bid + 6.0, 102.0)
        elif critical_opp and not scarcity:
            bid = max(18.0, prev_bid * 0.45)
        elif very_tight:
            bid = prev_bid + 4.0
        elif scarcity:
            bid = prev_bid + 2.0
        elif abundant:
            bid = max(22.0, prev_bid * 0.38)
        else:
            bid = max(35.0, prev_bid * 0.58)

    if day >= 8:
        bid += 8.0
    if day >= 9 and hp <= 3:
        bid += 10.0

    if opp_budget < bid and opp_budget > 0:
        bid = max(opp_budget + 1.0, bid)

    reserve = 0.0
    if day <= 7:
        reserve = max(0.0, (10 - day) * 8.0)
    max_affordable = max(0.0, budget - reserve)
    if critical_me:
        max_affordable = budget

    bid = min(bid, budget)
    if max_affordable > 0:
        bid = min(bid, max_affordable)

    if critical_me and bid < 85.0:
        bid = min(budget, 85.0)
    if scarcity and bid < 55.0 and not critical_opp:
        bid = min(budget, 55.0)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # If we are already in trouble, prioritize survival.
    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read only yesterday's immediate behavior from previous_trace.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # Estimate how competitive the market was yesterday.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Supply pressure: how many full water units exist.
    # Each agent needs WATER_REQ per day; supply is total.
    # Convert to an integer count of full units to avoid float index issues.
    units = int(supply // float(WATER_REQ))
    if units < 1:
        units = 1

    # Determine aggressiveness threshold from yesterday.
    # Cindy/Alex were bidding around ~95-98 avg; use that as a signal.
    competitive = highest_prev_bid >= (DAILY_SALARY * 0.85) or avg_prev_bid >= (DAILY_SALARY * 0.8)

    # Base bid depends on whether we are at risk.
    risk = 0
    if hp <= 2:
        risk += 2
    if no_water_days >= 1:
        risk += 1

    # If supply is tight (few units), bid closer to competitive band.
    tight_supply = units <= 2  # with supply 15-25 and WATER_REQ=9, units mostly 1-2

    # Compute target bid.
    if risk >= 2:
        # Survival mode: be willing to match aggression.
        if competitive and tight_supply:
            target = max(avg_prev_bid, highest_prev_bid * 0.9)
        else:
            target = DAILY_SALARY * 0.85
    else:
        # Healthy mode: avoid overpaying.
        if competitive and tight_supply:
            target = max(DAILY_SALARY * 0.65, avg_prev_bid * 0.75)
        elif competitive:
            target = max(DAILY_SALARY * 0.55, avg_prev_bid * 0.6)
        else:
            # If others weren't aggressive yesterday, bid moderately.
            target = DAILY_SALARY * 0.48

    # Cap by budget and keep within a reasonable range.
    # Also ensure we don't bid negative.
    bid = max(0.0, min(budget, float(target)))

    # If budget is extremely low, still bid something only if we must.
    if budget <= 1.0:
        return 0.0 if risk == 0 else 1.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 0.99)
    elif my_hp <= 4:
        return min(my_budget, DAILY_SALARY * 0.9)

    highest_prev_bid = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])

    if highest_prev_bid == 0.0:
        if current_day <= EPISODE_DAYS / 2 and my_hp > EPISODE_DAYS / 2:
            base_bid = DAILY_SALARY * 0.55
        else:
            base_bid = DAILY_SALARY * 0.7
        return min(my_budget, base_bid)

    target_bid = highest_prev_bid + 2.5

    if my_hp > 4:
        target_bid = min(target_bid, DAILY_SALARY * 0.85)

    final_bid = min(my_budget, target_bid)

    return max(1.0, final_bid)

